package java_programing.LoopExamples;

public class DisariumNum {

    public static void main(String[] args) {
        int num = new java.util.Scanner(System.in).nextInt();
        int sum = 0;
        int count = 0;

        for (int i = num; i > 0; i /= 10) {
            count++;
        }

        for (int i = num; i > 0; i /= 10) {
            int last = i % 10;
            int prod = 1;
            int countCopy = count;
            while (countCopy > 0) {
                prod *= last;
                countCopy--;
            }
            sum += prod;
            count--;
        }

        if (sum == num) {
            System.out.println(num + " is a Disarium Number");
        } else {
            System.out.println(num + " is not a Disarium Number");
        }
    }
}

package java_programing.NestedLoop;

public class NthDisariumNum {
    public static void main(String[] args) {
        int num = 10;
        int count = 0;
        int currentNum = 1;

        while (true) {
            int tempCount = 0;
            for (int i = currentNum; i > 0; i /= 10) {
                tempCount++;
            }

            int sum = 0;
            int temp = currentNum;
            int currentPower = tempCount;

            while (temp > 0) {
                int last = temp % 10;
                int prod = 1;
                for (int i = 0; i < currentPower; i++) {
                    prod *= last;
                }
                sum += prod;
                temp /= 10;
                currentPower--;
            }

            if (sum == currentNum) {
                count++;
                if (count == num) {
                    System.out.println("The " + num + "th Disarium Number is: " + currentNum);
                    break;
                }
            }
            currentNum++;
        }
    }
}

